// package.json with Husky configuration
{
  "name": "my-project",
  "scripts": {
    "prepare": "husky install",
    "lint": "eslint .",
    "test": "jest",
    "test:ci": "jest --ci --coverage"
  },
  "devDependencies": {
    "husky": "^8.0.0",
    "lint-staged": "^15.0.0",
    "eslint": "^8.0.0"
  },
  "lint-staged": {
    "*.js": ["eslint --fix", "git add"],
    "*.{js,ts,json,md}": ["prettier --write"]
  }
}

// Setup Husky
// npx husky-init && npm install
// Creates .husky/ directory with pre-commit hook

// .husky/pre-commit (created by Husky)
#!/usr/bin/env sh
. "$(dirname -- "$0")/_/husky.sh"

npx lint-staged

// .husky/commit-msg
#!/usr/bin/env sh
. "$(dirname -- "$0")/_/husky.sh"

npx --no -- commitlint --edit ${1}

// .husky/pre-push
#!/usr/bin/env sh
. "$(dirname -- "$0")/_/husky.sh"

npm run test:ci

// commitlint.config.js
module.exports = {
  extends: ['@commitlint/config-conventional'],
  rules: {
    'type-enum': [2, 'always', ['feat', 'fix', 'docs', 'style', 'refactor', 'test', 'chore']],
    'subject-max-length': [2, 'always', 72]
  }
};

// LEFTHOOK (language-agnostic, faster alternative)
// lefthook.yml in repository root
commit-msg:
  commands:
    commitlint:
      run: npx commitlint --edit {1}

pre-commit:
  parallel: true
  commands:
    eslint:
      glob: "*.{js,ts}"
      run: npx eslint {staged_files}
    prettier:
      glob: "*.{js,ts,json,md}"
      run: npx prettier --check {staged_files}
    test:
      run: npm test -- --findRelatedTests {staged_files}

pre-push:
  commands:
    test:
      run: npm run test:ci
    audit:
      run: npm audit --audit-level=moderate

// Install Lefthook: npx lefthook install
